-- session compaction message/protected-prefix utilities
-- Generated by merging focused helpers into an agent-discoverable module.

local history_core = require("maxa.session.history_core")
local wrapped_calls = require("maxa.interactions.chat.tools.builtin.runtime.wrapped_tool_calls")

local M = {}

M.is_tool_error = history_core.is_tool_error

