-- ============================================================
-- 压缩工具公共函数
-- ============================================================

-- 压缩模式常量
M.COMPRESS_MODE = {
  AUTO = "auto",
  OVERWRITE = "overwrite",
  NEW = "new",
}

M.PROTECTED_PREFIX_FIELD = "compact_protected_prefix_count"

local function normalize_non_negative_integer(value)
  local n = tonumber(value)
  if not n then
    return 0
  end
  n = math.floor(n)
  if n < 0 then
    return 0
  end
  return n
end

--- 获取会话的 protected initial prefix 长度。
--- 旧会话没有字段时返回 0。
---@param source_or_chat table|nil get_messages_source 返回值、chat 或 chat_data
---@return number
function M.get_protected_prefix_count(source_or_chat)
  if type(source_or_chat) ~= "table" then
    return 0
  end

  local candidates = {}
  if source_or_chat.chat or source_or_chat.chat_data then
    table.insert(candidates, source_or_chat.chat)
    table.insert(candidates, source_or_chat.chat_data)
  end
  table.insert(candidates, source_or_chat)

  for _, obj in ipairs(candidates) do
    if type(obj) == "table" then
      local direct = obj[M.PROTECTED_PREFIX_FIELD] or obj._compact_protected_prefix_count
      if direct ~= nil then
        return normalize_non_negative_integer(direct)
      end
      if type(obj.opts) == "table" then
        local from_opts = obj.opts[M.PROTECTED_PREFIX_FIELD]
        if from_opts ~= nil then
          return normalize_non_negative_integer(from_opts)
        end
      end
    end
  end

  return 0
end

--- 设置会话 protected initial prefix 长度。
---@param chat table|nil
---@param count number|nil
---@return number count
function M.set_protected_prefix_count(chat, count)
  local n = normalize_non_negative_integer(count)
  if type(chat) == "table" then
    chat._compact_protected_prefix_count = n
    chat.opts = chat.opts or {}
    chat.opts[M.PROTECTED_PREFIX_FIELD] = n
  end
  return n
end

--- 推断真正的不可压缩初始前缀长度。
--- 只把会话开头的系统提示词/项目规则等基础消息纳入 protected prefix，
--- 不把历史恢复出的整段消息纳入，避免 restored chat 被整体锁死无法压缩。
---@param messages table[]|nil
---@return number count
function M.infer_initial_protected_prefix_count(messages)
  if type(messages) ~= "table" then
    return 0
  end

  local count = 0
  for _, msg in ipairs(messages) do
    local meta = msg and (msg._meta or (msg.opts and msg.opts._meta) or {}) or {}
    local tag = meta.tag
    if msg and msg.role == "system" then
      count = count + 1
    elseif tag == "system_prompt_from_config" or tag == "rules" then
      count = count + 1
    else
      break
    end
  end

  return count
end

--- 将当前 messages 前缀标记为不可压缩初始消息。
---@param chat table|nil
---@param count number|nil 默认推断 system/rules 初始前缀，不再默认 #chat.messages
---@return number count
function M.mark_current_messages_as_protected_prefix(chat, count)
  if type(chat) ~= "table" then
    return 0
  end
  local n = count ~= nil and count or M.infer_initial_protected_prefix_count(chat.messages)
  return M.set_protected_prefix_count(chat, n)
end

---@param count number
---@return number first_compressible_index
function M.get_first_compressible_index(count)
  return normalize_non_negative_integer(count) + 1
end

---@param count number
---@return string
function M.format_protected_range(count)
  count = normalize_non_negative_integer(count)
  if count <= 0 then
    return "(none)"
  end
  return "1-" .. tostring(count)
end

local function compact_preview(value, max_chars)
  if value == nil then
    return ""
  end
  local text = type(value) == "string" and value or vim.inspect(value)
  text = text:gsub("\r\n", "\n"):gsub("\r", "\n"):gsub("%s+", " ")
  text = vim.trim(text)
  max_chars = max_chars or 180
  if #text > max_chars then
    text = text:sub(1, max_chars) .. "..."
  end
  return text
end

--- 构建 protected prefix 摘要，避免完整展开巨大系统提示词。
---@param messages table[]|nil
---@param count number
---@param opts table|nil
---@return string
function M.build_protected_prefix_summary(messages, count, opts)
  opts = opts or {}
  count = normalize_non_negative_integer(count)
  if count <= 0 then
    return "(no protected initial messages)"
  end
  local max_items = opts.max_items or 40
  local max_chars = opts.max_chars or 180
  local lines = {}
  local total = math.min(count, #(messages or {}))
  for i = 1, math.min(total, max_items) do
    local msg = messages[i] or {}
    local meta = msg._meta or (msg.opts and msg.opts._meta) or {}
    local tag = meta.tag and (" tag=" .. tostring(meta.tag)) or ""
    local context_id = msg.context and msg.context.id and (" context=" .. tostring(msg.context.id)) or ""
    local tool_hint = ""
    if msg.tools and msg.tools.calls and #msg.tools.calls > 0 then
      local names = {}
      for _, call in ipairs(msg.tools.calls) do
        local fn = call["function"]
        if fn and fn.name then
          table.insert(names, fn.name)
        end
      end
      if #names > 0 then
        tool_hint = " tools=" .. table.concat(names, ",")
      end
    end
    local preview = compact_preview(msg.content, max_chars)
    table.insert(lines, string.format("%d. role=%s%s%s%s | %s", i, tostring(msg.role), tag, context_id, tool_hint, preview))
  end
  if total > max_items then
    table.insert(lines, string.format("... (%d more protected messages omitted)", total - max_items))
  end
  if count > total then
    table.insert(lines, string.format("... (%d protected indices have no loaded message in current view)", count - total))
  end
  return table.concat(lines, "\n")
end

--- 构建给压缩 agent 的 protected prefix 提示。
---@param messages table[]|nil
---@param count number
---@return string
function M.build_protected_prefix_notice(messages, count)
  count = normalize_non_negative_integer(count)
  if count <= 0 then
    return ""
  end
  local first = M.get_first_compressible_index(count)
  return table.concat({
    "## Protected Initial Prefix (不可压缩初始消息)",
    "",
    "The saved session has a protected initial message prefix that is the foundation of this chat/session.",
    "You MUST NOT summarize, delete, collapse, replace, or clean any message inside this prefix.",
    "",
    string.format("- protected range: %s", M.format_protected_range(count)),
    string.format("- first compressible index: %d", first),
    "",
    "Hard constraints:",
    string.format("- Every `compact_range` range must use `start_index >= %d`.", first),
    string.format("- `collapse_tail.collapse_start_index` must be >= %d.", first),
    "- If a tool reports protected_prefix_overlap, repair the range and retry; do not stop.",
    "",
    "Protected prefix summary:",
    M.build_protected_prefix_summary(messages, count),
  }, "\n")
end

--- 构建 protected prefix 越界错误 payload。
---@param tool_name string
---@param protected_count number
---@param offending table
---@return table
function M.build_protected_prefix_error(tool_name, protected_count, offending)
  protected_count = normalize_non_negative_integer(protected_count)
  local first = M.get_first_compressible_index(protected_count)
  local payload = {
    status = "error",
    error_type = "protected_prefix_overlap",
    retryable = true,
    protected_prefix_count = protected_count,
    protected_range = M.format_protected_range(protected_count),
    first_compressible_index = first,
    offending_range = offending,
    suggested_action = "choose_start_index_at_or_after_first_compressible_index",
  }
  local actual = offending and (offending.start_index or offending.collapse_start_index) or nil
  local end_idx = offending and offending.end_index or nil
  if end_idx then
    payload.message = string.format(
      "%s: range %s-%s overlaps protected initial prefix %s. First compressible index is %d.",
      tool_name,
      tostring(actual),
      tostring(end_idx),
      payload.protected_range,
      first
    )
  else
    payload.message = string.format(
      "%s: start index %s overlaps protected initial prefix %s. First compressible index is %d.",
      tool_name,
      tostring(actual),
      payload.protected_range,
      first
    )
  end
  return payload
end

--- 校验普通压缩范围是否越过 protected prefix。
---@return table|nil error_payload
function M.validate_range_against_protected_prefix(start_index, end_index, protected_count, tool_name)
  protected_count = normalize_non_negative_integer(protected_count)
  if protected_count <= 0 then
    return nil
  end
  local first = M.get_first_compressible_index(protected_count)
  if tonumber(start_index) and tonumber(start_index) < first then
    return M.build_protected_prefix_error(tool_name or "compact_range", protected_count, {
      start_index = start_index,
      end_index = end_index,
    })
  end
  return nil
end

--- 校验 collapse 起点是否越过 protected prefix。
---@return table|nil error_payload
function M.validate_collapse_against_protected_prefix(collapse_start_index, protected_count, tool_name)
  protected_count = normalize_non_negative_integer(protected_count)
  if protected_count <= 0 then
    return nil
  end
  local first = M.get_first_compressible_index(protected_count)
  if tonumber(collapse_start_index) and tonumber(collapse_start_index) < first then
    return M.build_protected_prefix_error(tool_name or "collapse_tail", protected_count, {
      collapse_start_index = collapse_start_index,
    })
  end
  return nil
end

