-- Preserved current-runtime context tags. Retired Skill/MCP capability tags are
-- deliberately absent so pre-cut state cannot become active Ability context.
M.OK_TAGS = {
  "rules",
  "agent_boundary",
  "context_file",
  "ability_revision",
  "ability_instructions",
  "ability_guidance",
  "ability_catalog",
  "ability_reference",
  "ability_hook",
  "ability_hook_tombstone",
}

-- `load` is the only current capability/context loader. Its latest complete
-- catalog-bearing call/result pair is protected separately during deduplication.
M.OK_TOOL_CALLS = { "load" }

--- 检查 tag 是否在 OK_TAGS 中
---@param tag string|nil
---@return boolean
local function is_ok_tag(tag)
  if not tag then
    return false
  end
  for _, ok_tag in ipairs(M.OK_TAGS) do
    if tag == ok_tag then
      return true
    end
  end
  return false
end

--- 判断是否为自动注入的 token_warning 消息
---@param msg table
---@return boolean
local function is_token_warning_message(msg)
  if type(msg) ~= "table" then
    return false
  end

  if msg._meta and msg._meta.tag == "token_warning" then
    return true
  end

  local sk = msg.context and (msg.context.ability_hook or msg.context.skill_hook)
  if type(sk) ~= "table" then
    return false
  end

  local path = sk.path
  if type(path) == "string" and path:match("session%-admin/hooks/ChatSubmitted%.lua$") then
    return true
  end

  if type(sk.paths) == "table" then
    for _, p in ipairs(sk.paths) do
      if type(p) == "string" and p:match("session%-admin/hooks/ChatSubmitted%.lua$") then
        return true
      end
    end
  end

  return false
end

local RUNTIME_CONTROL_TAGS = {
  nvim_restart_resume = true,
  mcphub_restart_resume = true,
}

--- 判断是否为只用于当前运行时控制/恢复的消息。
--- 这些消息可帮助 agent 自动续跑，但不应落盘到历史或被 `/merge` 刷新成普通用户消息。
---@param msg table
---@return boolean
local function is_runtime_control_message(msg)
  if type(msg) ~= "table" then
    return false
  end
  local tag = msg._meta and msg._meta.tag
  if tag and RUNTIME_CONTROL_TAGS[tag] then
    return true
  end
  return false
end

function M.is_runtime_control_message(msg)
  return is_runtime_control_message(msg)
end

--- 移除所有运行时控制/恢复消息。
---@param messages table[]
---@return table[]
function M.strip_runtime_control_messages(messages)
  if not messages then
    return {}
  end

  local filtered = {}
  for _, msg in ipairs(messages) do
    if not is_runtime_control_message(msg) then
      table.insert(filtered, msg)
    end
  end
  return filtered
end

--- 移除所有 token_warning 消息（仅基于结构化 _meta 标记）
---@param messages table[]
---@return table[]
function M.strip_token_warning_messages(messages)
  if not messages then
    return {}
  end

  local filtered = {}
  for _, msg in ipairs(messages) do
    if not is_token_warning_message(msg) then
      table.insert(filtered, msg)
    end
  end
  return filtered
end

--- 检查工具名是否在 OK_TOOL_CALLS 中
---@param tool_name string|nil
---@return boolean
local function is_ok_tool_call(tool_name)
  if not tool_name then
    return false
  end
  for _, ok_tool in ipairs(M.OK_TOOL_CALLS) do
    if tool_name == ok_tool then
      return true
    end
  end
  return false
end

local function call_has_ok_semantic(call)
  for _, semantic in ipairs(wrapped_calls.expand_call(call)) do
    if is_ok_tool_call(semantic.tool_name) then
      return true
    end
  end
  return false
end

--- 从 assistant/llm 消息中提取保留的工具调用
--- 如果消息包含批量工具调用，只保留 OK_TOOL_CALLS 中的调用
---@param msg table 消息对象
---@return table|nil filtered_msg 过滤后的消息，nil 表示整条消息应移除
---@return table|nil kept_tool_ids 保留的工具调用 ID 列表
local function filter_tool_calls_in_message(msg)
  -- 检查是否有工具调用
  if not msg.tools or not msg.tools.calls or #msg.tools.calls == 0 then
    return nil, nil
  end

  local kept_calls = {}
  local kept_tool_ids = {}

  for _, call in ipairs(msg.tools.calls) do
    local func = call["function"]
    if (func and is_ok_tool_call(func.name)) or call_has_ok_semantic(call) then
      table.insert(kept_calls, call)
      local call_id = wrapped_calls.get_call_id(call)
      if call_id then
        table.insert(kept_tool_ids, call_id)
      end
    end
  end

  -- 如果没有保留的工具调用，返回 nil
  if #kept_calls == 0 then
    return nil, nil
  end

  -- 构建过滤后的消息
  local filtered_msg = vim.deepcopy(msg)
  filtered_msg.tools.calls = kept_calls

  return filtered_msg, kept_tool_ids
end

--- 检查 tool 消息是否对应保留的工具调用（且成功）
---@param msg table tool 消息
---@param kept_tool_ids table 保留的工具调用 ID 列表
---@return boolean is_kept 是否保留
---@return string|nil tool_call_id 对应的工具调用 ID（用于移除失败的调用）
local function is_kept_tool_response(msg, kept_tool_ids)
  if msg.role ~= "tool" then
    return false, nil
  end

  local tool_call_id = (msg.tools and msg.tools.call_id) or msg.tool_call_id

  -- 检查是否是错误响应（错误的调用不保留）
  if M.is_tool_error(msg) then
    -- 返回 tool_call_id 以便从 kept_tool_ids 中移除
    return false, tool_call_id
  end

  -- 检查 tool_call_id 是否在保留列表中
  if tool_call_id then
    for _, id in ipairs(kept_tool_ids) do
      if tool_call_id == id then
        return true, tool_call_id
      end
    end
  end

  -- 备用方案：通过 content 中的工具名匹配
  -- MaxaAI 格式: "**`tool_name` Tool**: Returned the following:"
  if msg.content and type(msg.content) == "string" then
    for _, ok_tool in ipairs(M.OK_TOOL_CALLS) do
      -- 只匹配成功的响应（包含 "Returned"）
      if msg.content:match("%*%*`" .. ok_tool .. "` Tool%*%*: Returned") then
        return true, nil
      end
    end
  end

  return false, nil
end

--- 过滤消息列表，保留符合规则的消息
--- 规则：
--- 1. 保留所有 system 消息
--- 2. 保留带 OK_TAGS 的 user 消息
--- 3. 保留 OK_TOOL_CALLS 中成功的工具调用（从批量调用中提取）
--- 4. 保留对应的成功 tool 结果消息
--- 5. 移除其他消息（包括失败的工具调用）
--- 6. 相同 context.id 的 context 消息只保留最后一条（force_reload 场景去重）
---    对应的旧 tool call pair 也一并移除
---@param messages table[] 原始消息列表
---@return table[] filtered 过滤后的消息列表

function M.is_ok_tag(tag)
  return is_ok_tag(tag)
end

function M.is_ok_tool_call(tool_name)
  return is_ok_tool_call(tool_name)
end

function M.filter_tool_calls_in_message(msg)
  return filter_tool_calls_in_message(msg)
end

function M.is_kept_tool_response(msg, kept_tool_ids)
  return is_kept_tool_response(msg, kept_tool_ids)
end

