local function is_ok_tool_call(tool_name)
  if not tool_name then
    return false
  end
  for _, ok_tool in ipairs(M.OK_TOOL_CALLS or {}) do
    if tool_name == ok_tool then
      return true
    end
  end
  return false
end

--- 对 context 消息按 context.id 去重，只保留最后一条
--- 同时移除被去重掉的 context 消息所关联的 tool call pair
---
--- 关联关系：OK_TOOL_CALLS 中统一 `load` 的成功调用
--- 会产生对应的 context 消息。当 context 消息被去重移除时，其对应的 tool call + tool result
--- 也应一并移除，避免孤立的 tool pair 占用空间。
---
--- 匹配规则（tool call 参数 → context.id）：
---   load: Markdown target → absolute context.id
---   load: Ability target → ability revision/instructions/guidance context ids
---   load: Ability reference target → ability:reference context id
---
---@param messages table[] 已过滤的消息列表
---@return table[] deduped 去重后的消息列表
function M.dedup_context_messages(messages)
  if not messages then
    return {}
  end

  -- 第一遍（从后往前）：记录每个 context.id 最后一次出现的位置
  local last_seen = {} -- context.id -> index (最后出现位置)
  for i = #messages, 1, -1 do
    local msg = messages[i]
    if msg.context and msg.context.id then
      if not last_seen[msg.context.id] then
        last_seen[msg.context.id] = i
      end
    end
  end

  -- Protect the catalog-bearing call associated with each retained Ability
  -- revision. A later ready/unchanged `load` must not supersede this pair.
  local protected_catalog_call_ids = {}
  for i, msg in ipairs(messages) do
    local ability = msg._meta and msg._meta.ability
    local context_id = msg.context and msg.context.id
    if ability and ability.kind == "revision" and context_id and last_seen[context_id] == i then
      if type(ability.catalog_call_id) == "string" and ability.catalog_call_id ~= "" then
        protected_catalog_call_ids[ability.catalog_call_id] = true
      end
    end
  end

  -- 检查是否有重复（任何 context.id 出现超过一次）
  local has_duplicates = false
  local seen_ids = {}
  for i, msg in ipairs(messages) do
    if msg.context and msg.context.id then
      if seen_ids[msg.context.id] then
        has_duplicates = true
        break
      end
      seen_ids[msg.context.id] = true
    end
  end

  if not has_duplicates then
    return messages
  end

  -- 收集要移除的 context 消息索引（不是最后一条的）
  local remove_context_indices = {} -- index -> true
  local removed_context_ids = {} -- context.id -> true (被去重移除的)
  for i, msg in ipairs(messages) do
    if msg.context and msg.context.id then
      if last_seen[msg.context.id] and last_seen[msg.context.id] ~= i then
        remove_context_indices[i] = true
        removed_context_ids[msg.context.id] = true
      end
    end
  end

  -- 如果没有需要移除的，直接返回
  if not next(removed_context_ids) then
    return messages
  end

  -- 第二遍：建立 tool_call_id → context.id 的映射
  -- 通过分析 OK_TOOL_CALLS 的参数来推断其关联的 context.id
  local call_id_to_context_ids = {} -- tool_call_id -> {context_id, ...}

  for _, msg in ipairs(messages) do
    if (msg.role == "llm" or msg.role == "assistant") and msg.tools and msg.tools.calls then
      for _, call in ipairs(msg.tools.calls) do
        local func = call["function"]
        local call_id = wrapped_calls.get_call_id(call)
        if func and call_id and (is_ok_tool_call(func.name) or call_has_ok_semantic(call)) then
          local context_ids = {}
          for _, semantic in ipairs(wrapped_calls.expand_call(call)) do
            if is_ok_tool_call(semantic.tool_name) then
              for _, context_id in ipairs(wrapped_calls.context_ids_for_loaded_call(semantic.tool_name, semantic.args)) do
                table.insert(context_ids, context_id)
              end
            end
          end

          if #context_ids > 0 then
            call_id_to_context_ids[call_id] = context_ids
          end
        end
      end
    end
  end

  -- 第三遍：确定要移除的 tool call IDs
  -- 一个 tool_call_id 只在其关联的 context 消息被去重移除时才移除
  -- 且只移除"不是最后一次成功调用"的 tool call pair
  --
  -- 逻辑：对于每个被去重的 context.id，找到所有关联的 tool_call_id，
  -- 保留最后一个成功的（与保留的 context 消息对应），移除其余的
  local context_id_to_call_ids = {} -- context.id -> {call_id, ...} (按出现顺序)

  -- 按消息顺序收集
  for _, msg in ipairs(messages) do
    if (msg.role == "llm" or msg.role == "assistant") and msg.tools and msg.tools.calls then
      for _, call in ipairs(msg.tools.calls) do
        local call_id = wrapped_calls.get_call_id(call)
        if call_id and call_id_to_context_ids[call_id] then
          for _, ctx_id in ipairs(call_id_to_context_ids[call_id]) do
            if not context_id_to_call_ids[ctx_id] then
              context_id_to_call_ids[ctx_id] = {}
            end
            table.insert(context_id_to_call_ids[ctx_id], call_id)
          end
        end
      end
    end
  end

  local remove_call_ids = {} -- tool_call_id -> true
  for ctx_id, call_ids in pairs(context_id_to_call_ids) do
    if removed_context_ids[ctx_id] and #call_ids > 1 then
      local keep_call_id = nil
      for _, call_id in ipairs(call_ids) do
        if protected_catalog_call_ids[call_id] then
          keep_call_id = call_id
        end
      end
      keep_call_id = keep_call_id or call_ids[#call_ids]
      for _, call_id in ipairs(call_ids) do
        if call_id ~= keep_call_id then
          remove_call_ids[call_id] = true
        end
      end
    end
  end

  -- 第四遍：构建去重后的消息列表
  local deduped = {}

  for i, msg in ipairs(messages) do
    local skip = false

    -- 跳过被去重的 context 消息
    if remove_context_indices[i] then
      skip = true
    end

    -- 跳过被移除的 tool result
    if not skip and msg.role == "tool" then
      local call_id = (msg.tools and msg.tools.call_id) or msg.tool_call_id
      if call_id and remove_call_ids[call_id] then
        skip = true
      end
    end

    -- 处理包含被移除 tool calls 的 llm 消息
    if not skip and (msg.role == "llm" or msg.role == "assistant") and msg.tools and msg.tools.calls then
      local has_removable = false
      for _, call in ipairs(msg.tools.calls) do
        local call_id = wrapped_calls.get_call_id(call)
        if call_id and remove_call_ids[call_id] then
          has_removable = true
          break
        end
      end

      if has_removable then
        local kept_calls = {}
        for _, call in ipairs(msg.tools.calls) do
          local call_id = wrapped_calls.get_call_id(call)
          if not (call_id and remove_call_ids[call_id]) then
            table.insert(kept_calls, call)
          end
        end

        if #kept_calls == 0 and (not msg.content or msg.content == "") then
          skip = true
        elseif #kept_calls == 0 then
          local cleaned_msg = vim.deepcopy(msg)
          cleaned_msg.tools = nil
          table.insert(deduped, cleaned_msg)
          skip = true
        else
          local cleaned_msg = vim.deepcopy(msg)
          cleaned_msg.tools.calls = kept_calls
          table.insert(deduped, cleaned_msg)
          skip = true
        end
      end
    end

    if not skip then
      table.insert(deduped, msg)
    end
  end

  return deduped
end

