function M.filter_messages_for_compact(messages)
  if not messages then
    return {}
  end

  -- 第一遍：收集所有工具调用 ID 和对应的 tool 结果状态
  local tool_call_success = {} -- tool_call_id -> boolean (是否成功)
  local pending_tool_ids = {} -- 待确认的工具调用 ID
  local persistent_ttl_ids = {} -- persistent TTL tool result IDs

  for _, msg in ipairs(messages) do
    if msg.role == "tool" then
      local tool_call_id = (msg.tools and msg.tools.call_id) or msg.tool_call_id
      local ttl_meta = msg._meta and msg._meta.ttl_result
      if tool_call_id and ttl_meta and ttl_meta.persistent == true and not M.is_tool_error(msg) then
        persistent_ttl_ids[tool_call_id] = true
        tool_call_success[tool_call_id] = true
      end
    end
  end

  for _, msg in ipairs(messages) do
    if msg.role == "llm" or msg.role == "assistant" then
      if msg.tools and msg.tools.calls then
        for _, call in ipairs(msg.tools.calls) do
          local func = call["function"]
          local call_id = wrapped_calls.get_call_id(call)
          if call_id and ((func and M.is_ok_tool_call(func.name)) or call_has_ok_semantic(call) or persistent_ttl_ids[call_id]) then
            pending_tool_ids[call_id] = true
          end
        end
      end
    elseif msg.role == "tool" then
      -- MaxaAI 格式: msg.tools.call_id
      -- 标准 OpenAI 格式: msg.tool_call_id
      local tool_call_id = (msg.tools and msg.tools.call_id) or msg.tool_call_id
      if tool_call_id and pending_tool_ids[tool_call_id] then
        -- 检查是否成功；persistent TTL 已在上方预标记成功
        tool_call_success[tool_call_id] = persistent_ttl_ids[tool_call_id] or not M.is_tool_error(msg)
      end
    end
  end

  -- 第二遍：过滤消息
  local filtered = {}

  for _, msg in ipairs(messages) do
    local keep = false
    local processed_msg = msg

    if msg.role == "system" then
      -- 规则 1: 保留所有 system 消息
      keep = true
    elseif msg.role == "user" then
      -- 规则 2: 检查 user 消息的 tag
      if msg._meta and M.is_ok_tag(msg._meta.tag) then
        keep = true
      end
    elseif msg.role == "llm" or msg.role == "assistant" then
      -- 规则 3: 检查是否有成功的工具调用
      if msg.tools and msg.tools.calls and #msg.tools.calls > 0 then
          local kept_calls = {}
          for _, call in ipairs(msg.tools.calls) do
            local func = call["function"]
            local call_id = wrapped_calls.get_call_id(call)
            if call_id and ((func and M.is_ok_tool_call(func.name)) or call_has_ok_semantic(call) or persistent_ttl_ids[call_id]) then
              -- 只保留成功的调用
              if tool_call_success[call_id] then
                table.insert(kept_calls, call)
              end
            end
          end

        if #kept_calls > 0 then
          processed_msg = vim.deepcopy(msg)
          processed_msg.tools.calls = kept_calls
          keep = true
        end
      end
    elseif msg.role == "tool" then
      -- 规则 4: 检查是否是成功的工具调用的结果
      -- MaxaAI 格式: msg.tools.call_id
      -- 标准 OpenAI 格式: msg.tool_call_id
      local tool_call_id = (msg.tools and msg.tools.call_id) or msg.tool_call_id
      if tool_call_id and tool_call_success[tool_call_id] then
        keep = true
      end
    end

    if keep then
      table.insert(filtered, processed_msg)
    end
  end

  -- 规则 6: context.id 去重 — 相同 context.id 只保留最后一条
  -- 场景：force_reload 导致同一文件/Ability 被多次加载，压缩时只需保留最新内容
  filtered = M.dedup_context_messages(filtered)

  return filtered
end

--- 从消息列表中提取区间内的保留消息
--- 用于 compact_range 的区间处理
---@param messages table[] 原始消息列表
---@param start_index number 起始索引
---@param end_index number 结束索引
---@return table[] filtered 过滤后的消息列表（仅区间内）
function M.filter_range_messages_for_compact(messages, start_index, end_index)
  if not messages then
    return {}
  end

  -- 提取区间内的消息
  local range_messages = {}
  for i = start_index, end_index do
    if messages[i] then
      table.insert(range_messages, messages[i])
    end
  end

  -- 应用统一的过滤规则
  return M.filter_messages_for_compact(range_messages)
end

--- 对 context 消息按 context.id 去重，只保留最后一条
--- 同时移除被去重掉的 context 消息所关联的 tool call pair
---
--- 关联关系：OK_TOOL_CALLS 中统一 `load` 的成功调用
--- 会产生对应的 context 消息。当 context 消息被去重移除时，其对应的 tool call + tool result
--- 也应一并移除，避免孤立的 tool pair 占用空间。
---
--- 匹配规则（tool call 参数 → context.id）：
---   load: Markdown target → absolute context.id
---   load: Ability target → ability revision/instructions/guidance context ids
---   load: Ability reference target → ability:reference context id
---
---@param messages table[] 已过滤的消息列表
---@return table[] deduped 去重后的消息列表

-- ============================================================
-- Source: utils/tool_pairs_analyze.lua
-- ============================================================

-- ============================================================
-- Tool Call 配对保护模块
-- ============================================================

--- 从消息中提取所有 tool_call_id（支持多种格式）
---@param msg table 消息对象
---@return table tool_call_ids 工具调用 ID 列表
local function extract_tool_call_ids(msg)
  local ids = {}

  -- MaxaAI 格式: msg.tools.calls[].call_id (fallback to id for single-ID adapters)
  if msg.tools and msg.tools.calls then
    for _, call in ipairs(msg.tools.calls) do
      local call_id = wrapped_calls.get_call_id(call)
      if call_id then
        table.insert(ids, call_id)
      end
    end
  end

  -- OpenAI 格式: msg.tool_calls[].id
  if msg.tool_calls then
    for _, tc in ipairs(msg.tool_calls) do
      if tc.id then
        table.insert(ids, tc.id)
      end
    end
  end

  -- Anthropic 格式: msg.content[].id (type == "tool_use")
  if msg.content and type(msg.content) == "table" then
    for _, block in ipairs(msg.content) do
      if block.type == "tool_use" and block.id then
        table.insert(ids, block.id)
      end
    end
  end

  return ids
end

--- 从 tool 消息中提取对应的 tool_call_id
---@param msg table tool 消息
---@return string|nil tool_call_id
local function extract_tool_response_id(msg)
  if msg.role ~= "tool" then
    return nil
  end

  -- MaxaAI 格式
  if msg.tools and msg.tools.call_id then
    return msg.tools.call_id
  end

  -- OpenAI 格式
  if msg.tool_call_id then
    return msg.tool_call_id
  end

  -- Anthropic 格式: msg.content[].tool_use_id (type == "tool_result")
  if msg.content and type(msg.content) == "table" then
    for _, block in ipairs(msg.content) do
      if block.type == "tool_result" and block.tool_use_id then
        return block.tool_use_id
      end
    end
  end

  return nil
end

--- 分析消息列表中的 tool call 配对关系
--- 返回每个 tool_call_id 的调用位置和响应位置
---@param messages table[] 消息列表
---@return table tool_pairs {[tool_call_id] = {call_index, response_index}}
---@return table orphan_calls 孤立的 tool call 索引列表
---@return table orphan_responses 孤立的 tool response 索引列表
function M.analyze_tool_pairs(messages)
  if not messages then
    return {}, {}, {}
  end

  local tool_pairs = {} -- tool_call_id -> {call_index, response_index}
  local call_positions = {} -- tool_call_id -> call_index

  -- 第一遍：收集所有 tool call 位置
  for i, msg in ipairs(messages) do
    if msg.role == "llm" or msg.role == "assistant" then
      local ids = extract_tool_call_ids(msg)
      for _, id in ipairs(ids) do
        call_positions[id] = i
        tool_pairs[id] = { call_index = i, response_index = nil }
      end
    end
  end

  -- 第二遍：匹配 tool response
  for i, msg in ipairs(messages) do
    if msg.role == "tool" then
      local id = extract_tool_response_id(msg)
      if id and tool_pairs[id] then
        tool_pairs[id].response_index = i
      elseif id then
        -- 孤立的 response（没有对应的 call）
        tool_pairs[id] = { call_index = nil, response_index = i }
      end
    end
  end

  -- 分类孤立消息
  local orphan_calls = {}
  local orphan_responses = {}

  for id, pair in pairs(tool_pairs) do
    if pair.call_index and not pair.response_index then
      table.insert(orphan_calls, { id = id, index = pair.call_index })
    elseif pair.response_index and not pair.call_index then
      table.insert(orphan_responses, { id = id, index = pair.response_index })
    end
  end

  return tool_pairs, orphan_calls, orphan_responses
end

--- 检查索引范围是否会切断 tool call 配对
--- 返回安全的调整后范围
---@param messages table[] 消息列表
---@param start_index number 起始索引
---@param end_index number 结束索引
---@return number safe_start 安全的起始索引
---@return number safe_end 安全的结束索引
---@return table adjustments 调整说明列表

--- 验证消息列表中的 tool call 配对完整性
---@param messages table[] 消息列表
---@return boolean valid 是否所有配对都完整
---@return table issues 问题列表
function M.validate_tool_pairs(messages)
  if not messages then
    return true, {}
  end

  local _, orphan_calls, orphan_responses = M.analyze_tool_pairs(messages)
  local issues = {}

  for _, orphan in ipairs(orphan_calls) do
    table.insert(issues, {
      type = "missing_response",
      index = orphan.index,
      tool_call_id = orphan.id,
      message = string.format("Tool call at index %d (id: %s) has no response", orphan.index, orphan.id),
    })
  end

  for _, orphan in ipairs(orphan_responses) do
    table.insert(issues, {
      type = "missing_call",
      index = orphan.index,
      tool_call_id = orphan.id,
      message = string.format("Tool response at index %d (id: %s) has no call", orphan.index, orphan.id),
    })
  end

  return #issues == 0, issues
end

-- ============================================================
-- Source: utils/tool_pairs_clean.lua
-- ============================================================

--- 检查索引范围是否会切断 tool call 配对
--- 返回安全的调整后范围
---@param messages table[] 消息列表
---@param start_index number 起始索引
---@param end_index number 结束索引
---@return number safe_start 安全的起始索引
---@return number safe_end 安全的结束索引
---@return table adjustments 调整说明列表
function M.get_safe_range_for_tool_pairs(messages, start_index, end_index)
  if not messages then
    return start_index, end_index, {}
  end

  local tool_pairs, _, _ = M.analyze_tool_pairs(messages)
  local adjustments = {}
  local safe_start = start_index
  local safe_end = end_index

  -- 检查每个配对是否被切断
  for id, pair in pairs(tool_pairs) do
    local call_idx = pair.call_index
    local resp_idx = pair.response_index

    if call_idx and resp_idx then
      -- 情况 1: call 在范围内，response 在范围外（后面）
      if call_idx >= safe_start and call_idx <= safe_end and resp_idx > safe_end then
        -- 扩展 end 以包含 response
        safe_end = resp_idx
        table.insert(adjustments, {
          type = "extend_end",
          reason = string.format("tool_call %s at %d has response at %d", id, call_idx, resp_idx),
          old_end = end_index,
          new_end = resp_idx,
        })
      end

      -- 情况 2: response 在范围内，call 在范围外（前面）
      if resp_idx >= safe_start and resp_idx <= safe_end and call_idx < safe_start then
        -- 扩展 start 以包含 call
        safe_start = call_idx
        table.insert(adjustments, {
          type = "extend_start",
          reason = string.format("tool_response %s at %d has call at %d", id, resp_idx, call_idx),
          old_start = start_index,
          new_start = call_idx,
        })
      end

      -- 情况 3: call 在范围外（前面），response 在范围外（后面）
      -- 这种情况范围在配对中间，需要特殊处理
      if call_idx < safe_start and resp_idx > safe_end then
        -- 整个范围在一个 tool call 配对中间，这是危险的
        -- 选择：要么包含整个配对，要么排除整个配对
        -- 这里选择包含整个配对（更安全）
        safe_start = call_idx
        safe_end = resp_idx
        table.insert(adjustments, {
          type = "include_pair",
          reason = string.format("range is inside tool_call pair %s (%d-%d)", id, call_idx, resp_idx),
          old_range = { start_index, end_index },
          new_range = { call_idx, resp_idx },
        })
      end
    end
  end

  return safe_start, safe_end, adjustments
end

--- 清理消息列表中的孤立 tool 消息（双向检查）
--- 移除没有配对的 tool call 和 tool response
---@param messages table[] 消息列表
---@return table[] cleaned 清理后的消息列表
---@return table removed 被移除的消息信息
function M.clean_orphan_tool_messages(messages)
  if not messages then
    return {}, {}
  end

  local tool_pairs, orphan_calls, orphan_responses = M.analyze_tool_pairs(messages)
  local removed = {}

  -- 收集需要移除的索引
  local remove_indices = {}

  -- 移除孤立的 tool call
  for _, orphan in ipairs(orphan_calls) do
    remove_indices[orphan.index] = true
    table.insert(removed, {
      type = "orphan_call",
      index = orphan.index,
      tool_call_id = orphan.id,
    })
  end

  -- 移除孤立的 tool response
  for _, orphan in ipairs(orphan_responses) do
    remove_indices[orphan.index] = true
    table.insert(removed, {
      type = "orphan_response",
      index = orphan.index,
      tool_call_id = orphan.id,
    })
  end

  -- 对于包含多个 tool_calls 的消息，需要特殊处理
  -- 如果消息中部分 tool_call 有响应，部分没有，需要过滤掉没有响应的
  local cleaned = {}

  for i, msg in ipairs(messages) do
    if remove_indices[i] then
      -- 跳过需要移除的消息
    elseif (msg.role == "llm" or msg.role == "assistant") and msg.tools and msg.tools.calls then
      -- 检查是否需要过滤部分 tool_calls
      local kept_calls = {}
      local removed_calls = {}

      for _, call in ipairs(msg.tools.calls) do
        local call_id = wrapped_calls.get_call_id(call)
        if call_id then
          local pair_info = tool_pairs[call_id]
          if pair_info and pair_info.response_index then
            table.insert(kept_calls, call)
          else
            table.insert(removed_calls, call)
          end
        else
          table.insert(kept_calls, call)
        end
      end

      if #removed_calls > 0 then
        table.insert(removed, {
          type = "partial_calls_removed",
          index = i,
          removed_count = #removed_calls,
          kept_count = #kept_calls,
        })
      end

      if #kept_calls > 0 then
        local filtered_msg = vim.deepcopy(msg)
        filtered_msg.tools.calls = kept_calls
        table.insert(cleaned, filtered_msg)
      elseif msg.content and msg.content ~= "" then
        -- 如果消息有文本内容，保留文本部分
        local text_only_msg = vim.deepcopy(msg)
        text_only_msg.tools = nil
        table.insert(cleaned, text_only_msg)
      end
      -- 如果既没有保留的 calls 也没有文本内容，整条消息被移除
    else
      table.insert(cleaned, msg)
    end
  end

  return cleaned, removed
end

return M
